package ru.meguboom.mobile;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.media.*;import android.media.session.*;import android.net.Uri;import org.json.*;import java.net.*;import java.io.*;import java.util.Locale;import com.google.android.gms.auth.api.identity.*;import com.google.android.gms.common.api.Scope;

public class AudioService extends Service {
 public static volatile String snapshot="{}";public static volatile boolean active=false;
 final java.util.concurrent.ExecutorService io=java.util.concurrent.Executors.newSingleThreadExecutor();
 final java.util.concurrent.ExecutorService artworkIo=java.util.concurrent.Executors.newSingleThreadExecutor();
 final Handler handler=new Handler(Looper.getMainLooper());
 NativeProgress progress;String playbackAccount="";long appliedProgress=0,lastBackgroundSync=0;MediaPlayer player;MediaSession session;AudioManager audio;AudioFocusRequest focus;
 String id="",title="",artist="",cover="",kind="music",error="",completed="";
 JSONArray queue=new JSONArray();int queueIndex=-1,queueRequest=0,shuffleCursor=0;int[] shuffleOrder=new int[0];boolean shuffled=false;String repeatMode="off",queueToken="";
 boolean ready=false,loading=false;long lastSaved=0,sleepUntil=0;float speed=1;Bitmap artwork;int generation=0;
 final Runnable tick=new Runnable(){public void run(){if(!active)return;if(System.currentTimeMillis()-lastBackgroundSync>30000){lastBackgroundSync=System.currentTimeMillis();progress.request(false,null);}if(sleepUntil>0&&SystemClock.elapsedRealtime()>=sleepUntil){sleepUntil=0;toggle(false);saveProgress();}publish();handler.postDelayed(this,500);}};
 @Override public void onCreate(){super.onCreate();progress=NativeProgress.get(this);active=true;speed=getSharedPreferences("player",0).getInt("speed",100)/100f;if(speed<.5f||speed>3f)speed=1;
  getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("playback","Музыка и аудиокниги",NotificationManager.IMPORTANCE_LOW));
  audio=getSystemService(AudioManager.class);focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(change->{if(change<0&&ready&&player!=null)toggle(false);}).build();
  session=new MediaSession(this,"MeguBoom");session.setSessionActivity(openPlayer());session.setCallback(new MediaSession.Callback(){
   @Override public void onPlay(){toggle(true);}@Override public void onPause(){toggle(false);}@Override public void onStop(){saveProgress();stopSelf();}
   @Override public void onSeekTo(long position){seek(position);}@Override public void onRewind(){seekBy(-5000);}@Override public void onFastForward(){seekBy(5000);}
   @Override public void onSkipToNext(){advance(1,false);}@Override public void onSkipToPrevious(){advance(-1,false);}
   @Override public void onSetPlaybackSpeed(float value){changeSpeed(value);}
   @Override public void onCustomAction(String action,Bundle extras){handleControl(action,0);}
  });session.setActive(true);handler.post(tick);
 }
 PendingIntent openPlayer(){return PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).putExtra("showPlayer",true).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 PlaybackControls.Player controls(){return new PlaybackControls.Player(){public long position(){return player.getCurrentPosition();}public long duration(){return player.getDuration();}public boolean playing(){return player.isPlaying();}public void seek(long p){player.seekTo(p,MediaPlayer.SEEK_CLOSEST);}public void speed(float value){player.setPlaybackParams(new PlaybackParams().allowDefaults().setSpeed(value));}public void pause(){player.pause();}};}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null){stopSelf();return START_NOT_STICKY;}startForeground(1,notification());try{
  if("queue".equals(intent.getAction())){queue=new JSONArray(intent.getStringExtra("items"));for(int n=0;n<queue.length();n++)progress.register(queue.getJSONObject(n));queueToken=intent.getStringExtra("token");shuffled=intent.getBooleanExtra("shuffle",false);repeatMode=intent.getStringExtra("repeat");queueIndex=-1;for(int i=0;i<queue.length();i++)if(queue.getJSONObject(i).optString("id").equals(intent.getStringExtra("current")))queueIndex=i;resetShuffle();if(queueIndex<0){error="Запись не найдена в очереди. Откройте её заново.";publish();notifyState();}else openQueued();}else if("play".equals(intent.getAction())){queue=new JSONArray();queueIndex=-1;open(intent);}else handleControl(intent.getAction(),intent.getLongExtra("value",0));
 }catch(Exception e){error="Не удалось выполнить действие с аудио. Откройте запись заново.";loading=false;publish();notifyState();}return START_NOT_STICKY;}
 void open(Intent intent){saveProgress();releasePlayer();final int current=++generation;id=intent.getStringExtra("id");title=intent.getStringExtra("title");artist=intent.getStringExtra("artist");cover=intent.getStringExtra("cover");kind=intent.getStringExtra("kind");if(artist==null)artist="";if(cover==null)cover="";if(kind==null)kind="music";error="";completed="";artwork=null;loading=true;
  player=new MediaPlayer();final MediaPlayer pending=player;pending.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);pending.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType("book".equals(kind)?AudioAttributes.CONTENT_TYPE_SPEECH:AudioAttributes.CONTENT_TYPE_MUSIC).build());
  pending.setOnPreparedListener(p->{if(player!=p)return;ready=true;loading=false;playbackAccount=progress.account;PlaybackControls.setSpeed(controls(),speed);int saved=(int)Math.min(Integer.MAX_VALUE,progress.position(id));appliedProgress=progress.record(id).optLong("updatedAt");if(saved>0&&saved<p.getDuration()-1500)p.seekTo(saved,MediaPlayer.SEEK_CLOSEST);if(audio.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED)p.start();updateMetadata();publish();notifyState();});
  pending.setOnCompletionListener(p->{if(player!=p)return;completed=id;progress.local(id,p.getDuration(),p.getDuration(),true,true);java.util.Set<String> done=new java.util.HashSet<>(getSharedPreferences("progress",0).getStringSet("completedIds",java.util.Collections.emptySet()));done.add(id);getSharedPreferences("progress",0).edit().putStringSet("completedIds",done).apply();getSharedPreferences("progress",0).edit().putInt(id,0).apply();publish();notifyState();if(queue.length()>0)handler.postDelayed(()->{if(player==p)advance(1,true);},600);});
  pending.setOnErrorListener((p,what,extra)->{if(player==p){error="Не удалось открыть аудио. Проверьте доступ к файлу или подключите Google Диск заново.";ready=false;loading=false;publish();notifyState();}return true;});
  final Uri uri=Uri.parse(intent.getStringExtra("uri"));final String access=intent.getStringExtra("token");final String art=cover;
  io.execute(()->{try{if(access!=null&&!access.isEmpty()){String file=intent.getStringExtra("fileId");if(!ProgressRecords.validId(file))throw new IOException();FolderAccess.require(file,access);}if(access!=null&&!access.isEmpty())pending.setDataSource(this,uri,java.util.Collections.singletonMap("Authorization","Bearer "+access));else pending.setDataSource(this,uri);handler.post(()->{if(active&&player==pending)progress.beforePlay(()->{if(active&&player==pending)pending.prepareAsync();});});}catch(Exception e){handler.post(()->{if(active&&player==pending){error="Файл недоступен. Проверьте доступ к хранилищу.";ready=false;loading=false;publish();notifyState();}});}});
  artworkIo.execute(()->{Bitmap bitmap=loadArtwork(art);handler.post(()->{if(active&&current==generation){artwork=bitmap;updateMetadata();notifyState();}});});updateMetadata();publish();notifyState();
 }
 void handleControl(String action,long value){if(action==null)return;switch(action){case "disconnectDrive":queueRequest++;for(int i=0;i<queue.length();i++)if("drive".equals(queue.optJSONObject(i).optString("storage"))){queue=new JSONArray();queueIndex=-1;break;}if(id.startsWith("drive-")){saveProgress();stopSelf();}else publish();break;case "previous":advance(-1,false);break;case "next":advance(1,false);break;case "shuffle":shuffled=value!=0;resetShuffle();publish();break;case "repeat":repeatMode=value==2?"one":value==1?"all":"off";publish();break;case "toggle":if(ready)toggle(!player.isPlaying());break;case "seek":seek(value);break;case "back5":seekBy(-5000);break;case "forward5":seekBy(5000);break;case "speed":changeSpeed(value/100f);break;case "speedNext":changeSpeed(PlaybackControls.nextSpeed(speed));break;case "sleep":sleepUntil=value>0?SystemClock.elapsedRealtime()+Math.min(value,180)*60000:0;publish();notifyState();break;case "stop":saveProgress();stopSelf();break;}}
 void resetShuffle(){shuffleOrder=PlaybackQueue.order(queue.length(),queueIndex,new java.util.Random());shuffleCursor=0;}
 void openQueued(){try{JSONObject b=queue.getJSONObject(queueIndex);final int request=++queueRequest;boolean cloud="drive".equals(b.optString("storage"));if(cloud){loading=true;publish();notifyState();AuthorizationRequest auth=AuthorizationRequest.builder().setRequestedScopes(NativeProgress.SCOPES).build();Identity.getAuthorizationClient(this).authorize(auth).addOnSuccessListener(result->{if(!active||request!=queueRequest)return;if(result.hasResolution()||result.getAccessToken()==null){loading=false;error="Подключите Google Диск заново, чтобы продолжить очередь.";publish();notifyState();return;}openQueueRecord(b,result.getAccessToken());}).addOnFailureListener(e->{if(active&&request==queueRequest){loading=false;error="Не удалось обновить доступ к Google Диску. Подключите его заново.";publish();notifyState();}});}else openQueueRecord(b,"");}catch(Exception e){error="Запись в очереди недоступна";publish();}}
 void openQueueRecord(JSONObject b,String token){if(!FolderAccess.ROOT.equals(b.optString("allowedRoot"))||"local".equals(b.optString("storage"))&&!b.optString("accountId").equals(progress.account)){error="Запись вне выбранной папки";loading=false;publish();return;}progress.register(b);boolean cloud="drive".equals(b.optString("storage"));Intent i=new Intent().putExtra("id",b.optString("id")).putExtra("uri",cloud?"https://www.googleapis.com/drive/v3/files/"+b.optString("fileId")+"?alt=media":b.optString("uri")).putExtra("token",token).putExtra("title",b.optString("title",b.optString("name"))).putExtra("artist",b.optString("author",b.optString("artist"))).putExtra("cover",b.optString("cover")).putExtra("kind",b.optString("kind","music")).putExtra("fileId",ProgressRecords.fileId(b)).putExtra("allowedRoot",b.optString("allowedRoot"));open(i);}
 void advance(int direction,boolean automatic){int next;if(shuffled){int cursor=PlaybackQueue.next(shuffleCursor,shuffleOrder.length,direction,automatic,repeatMode,false,0);if(cursor<0)return;shuffleCursor=cursor;next=shuffleOrder[cursor];}else next=PlaybackQueue.next(queueIndex,queue.length(),direction,automatic,repeatMode,false,0);if(next<0)return;queueIndex=next;openQueued();}
 void changeSpeed(float value){if(Float.isNaN(value)||Float.isInfinite(value)||value<.5f||value>3f)return;try{if(ready&&player!=null)PlaybackControls.setSpeed(controls(),value);speed=value;updateMetadata();getSharedPreferences("player",0).edit().putInt("speed",Math.round(speed*100)).apply();publish();notifyState();}catch(Exception e){error="Не удалось изменить скорость";publish();}}
 void seek(long position){if(!ready||player==null)return;long target=Math.max(0,Math.min(player.getDuration(),position));progress.local(id,target,player.getDuration(),false,true);appliedProgress=progress.record(id).optLong("updatedAt");player.seekTo(target,MediaPlayer.SEEK_CLOSEST);completed="";clearCompletion();publish();}
 void seekBy(long offset){if(!ready||player==null)return;seek((long)player.getCurrentPosition()+offset);}
 void clearCompletion(){java.util.Set<String> done=new java.util.HashSet<>(getSharedPreferences("progress",0).getStringSet("completedIds",java.util.Collections.emptySet()));done.remove(id);getSharedPreferences("progress",0).edit().putStringSet("completedIds",done).apply();}
 void toggle(boolean play){if(!ready||player==null)return;if(play){if(id.equals(completed)||progress.record(id).optBoolean("completed")){completed="";player.seekTo(0,MediaPlayer.SEEK_CLOSEST);progress.local(id,0,player.getDuration(),false,true);clearCompletion();}else if(!player.isPlaying()){long saved=progress.position(id);if(saved>=0&&saved<player.getDuration())player.seekTo(saved,MediaPlayer.SEEK_CLOSEST);}if(audio.requestAudioFocus(focus)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED)player.start();}else{saveProgress();player.pause();progress.request(true,null);}publish();notifyState();}
 void saveProgress(){if(ready&&player!=null&&playbackAccount.equals(progress.account)&&!id.equals(completed))try{if(player.isPlaying()){int pos=player.getCurrentPosition();getSharedPreferences("progress",0).edit().putInt(id,pos).apply();progress.local(id,pos,player.getDuration(),false,false);appliedProgress=progress.record(id).optLong("updatedAt");}}catch(Exception ignored){}}
 void updateMetadata(){MediaMetadata.Builder metadata=new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).putString(MediaMetadata.METADATA_KEY_ARTIST,(artist.isEmpty()?"MeguBoom":artist)+" · "+speedLabel()).putString(MediaMetadata.METADATA_KEY_DISPLAY_TITLE,title).putString(MediaMetadata.METADATA_KEY_DISPLAY_SUBTITLE,(artist.isEmpty()?"MeguBoom":artist)+" · "+speedLabel()).putLong(MediaMetadata.METADATA_KEY_DURATION,ready&&player!=null?player.getDuration():0);if(artwork!=null)metadata.putBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART,artwork).putBitmap(MediaMetadata.METADATA_KEY_ART,artwork);session.setMetadata(metadata.build());}
 String speedLabel(){return String.format(Locale.ROOT,"%.2f",speed).replaceAll("0+$","").replaceAll("\\.$","")+"×";}
 void publish(){try{if(ready&&!playbackAccount.equals(progress.account)){releasePlayer();queue=new JSONArray();queueIndex=-1;id="";error="Аккаунт Google изменён. Откройте запись в библиотеке заново.";}boolean playing=ready&&player!=null&&player.isPlaying();if(ready&&!playing){JSONObject remote=progress.record(id);if(!remote.optBoolean("completed")&&id.equals(completed))completed="";if(remote.optLong("updatedAt")>appliedProgress&&!progress.device.equals(remote.optString("deviceId"))){appliedProgress=remote.optLong("updatedAt");long resume=remote.optBoolean("completed")?0:remote.optLong("positionMs");if(resume<player.getDuration())player.seekTo(resume,MediaPlayer.SEEK_CLOSEST);completed=remote.optBoolean("completed")?id:"";}}int position=ready?player.getCurrentPosition():0,duration=ready?player.getDuration():0;JSONObject s=new JSONObject();s.put("id",id);s.put("queueIndex",queueIndex);s.put("shuffle",shuffled);s.put("repeat",repeatMode);JSONArray ids=new JSONArray();for(int i=0;i<queue.length();i++)ids.put(queue.optJSONObject(i).optString("id"));s.put("queue",ids);JSONArray queueItems=new JSONArray();for(int i=0;i<queue.length();i++){JSONObject safe=new JSONObject(),raw=queue.getJSONObject(i);for(String key:java.util.Arrays.asList("id","title","name","author","artist","series","cover","kind","storage","fileId","catalogPath","downloadOf","allowedRoot","accountId"))if(raw.has(key))safe.put(key,raw.get(key));queueItems.put(safe);}s.put("queueItems",queueItems);s.put("completedIds",new JSONArray(getSharedPreferences("progress",0).getStringSet("completedIds",java.util.Collections.emptySet())));s.put("title",title);s.put("artist",artist);s.put("cover",cover);s.put("kind",kind);s.put("speed",Math.round(speed*100));s.put("sleepRemaining",Math.max(0,sleepUntil-SystemClock.elapsedRealtime()));s.put("loading",loading);s.put("error",error);s.put("completed",completed);s.put("playing",playing);s.put("position",position);s.put("duration",duration);snapshot=s.toString();if(System.currentTimeMillis()-lastSaved>5000){saveProgress();lastSaved=System.currentTimeMillis();}
  PlaybackState.Builder state=new PlaybackState.Builder().setActions(PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_REWIND|PlaybackState.ACTION_FAST_FORWARD|PlaybackState.ACTION_STOP|PlaybackState.ACTION_SET_PLAYBACK_SPEED).setState(loading?PlaybackState.STATE_BUFFERING:playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,position,playing?speed:0);
  state.addCustomAction("back5","Назад на 5 секунд",R.drawable.ic_back5).addCustomAction("forward5","Вперёд на 5 секунд",R.drawable.ic_forward5).addCustomAction("speedNext","Скорость "+speedLabel(),R.drawable.ic_speed).addCustomAction("stop","Закрыть плеер",R.drawable.ic_stop);session.setPlaybackState(state.build());
 }catch(Exception ignored){}}
 PendingIntent action(String name){return PendingIntent.getService(this,name.hashCode(),new Intent(this,AudioService.class).setAction(name),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 Notification notification(){boolean playing=ready&&player!=null&&player.isPlaying();Notification.Builder n=new Notification.Builder(this,"playback").setSmallIcon(R.drawable.app_icon).setContentTitle(title==null||title.isEmpty()?"MeguBoom":title).setContentText(loading?"Открываем аудио…":!error.isEmpty()?error:(artist.isEmpty()?"MeguBoom":artist)+" · "+speedLabel()).setSubText(speedLabel()+(sleepUntil>0?" · Таймер сна":"")).setContentIntent(openPlayer()).setOnlyAlertOnce(true).setOngoing(playing).setVisibility(Notification.VISIBILITY_PUBLIC).setColor(0xffd75163).setColorized(true).setCategory(Notification.CATEGORY_TRANSPORT);
  if(artwork!=null)n.setLargeIcon(artwork);
  n.addAction(new Notification.Action.Builder(R.drawable.ic_back5,"book".equals(kind)?"−5 с":"Предыдущая",action("book".equals(kind)?"back5":"previous")).build()).addAction(new Notification.Action.Builder(playing?R.drawable.ic_pause:R.drawable.ic_play,playing?"Пауза":"Слушать",action("toggle")).build()).addAction(new Notification.Action.Builder(R.drawable.ic_forward5,"book".equals(kind)?"+5 с":"Следующая",action("book".equals(kind)?"forward5":"next")).build()).addAction(new Notification.Action.Builder(R.drawable.ic_speed,"Скорость "+speedLabel(),action("speedNext")).build()).addAction(new Notification.Action.Builder(R.drawable.ic_stop,"Закрыть",action("stop")).build()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2));return n.build();
 }
 Bitmap loadArtwork(String url){try{byte[] bytes;if(url!=null&&url.startsWith("https://")){HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);try{if(c.getResponseCode()!=200)return fallbackArt();try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>4194304)return fallbackArt();out.write(b,0,n);}bytes=out.toByteArray();}}finally{c.disconnect();}}else return fallbackArt();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>768)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);return bitmap!=null?bitmap:fallbackArt();}catch(Exception e){return fallbackArt();}}
 Bitmap fallbackArt(){try(InputStream in=getAssets().open("app-icon.png")){return BitmapFactory.decodeStream(in);}catch(Exception e){return null;}}
 void notifyState(){if(active)getSystemService(NotificationManager.class).notify(1,notification());}
 void releasePlayer(){ready=false;if(player!=null){player.release();player=null;}}
 @Override public void onDestroy(){saveProgress();progress.request(true,null);generation++;queueRequest++;io.shutdownNow();artworkIo.shutdownNow();handler.removeCallbacksAndMessages(null);releasePlayer();audio.abandonAudioFocusRequest(focus);session.release();active=false;try{JSONObject s=new JSONObject(snapshot);s.put("playing",false);s.put("loading",false);snapshot=s.toString();}catch(Exception ignored){}stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
